pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, c.MinSum(), type(uint128).max);
        unlockTime = bound(unlockTime, 0, block.timestamp);
        address actor = address(0xBEEF);
        vm.deal(actor, amount);

        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        vm.warp(block.timestamp + 1);

        vm.prank(actor);
        c.Collect(amount);

        (uint256 unlockTimeStored, uint256 balanceStored) = c.Acc(actor);
        unlockTimeStored;
        assertTrue(balanceStored == 0);
    }
}
